      [ 2,  0, -2,  0, -1,  0,  0,  0,     0.14e-6,   0.00e-6 ],
      [ 0,  1,  2, -2,  2,  0,  0,  0,     0.14e-6,   0.00e-6 ],
      [ 1,  0,  0, -2,  1,  0,  0,  0,    -0.14e-6,   0.00e-6 ],
      [ 1,  0,  0, -2, -1,  0,  0,  0,    -0.14e-6,   0.00e-6 ],
