        [2, -1,  0,  0,  0.045758,   -204586.0],
        [0,  1, -1,  0, -0.040923,   -129620.0],
        [1,  0,  0,  0, -0.034720,    108743.0],
        [0,  1,  1,  0, -0.030383,    104755.0],
        [2,  0,  0, -2,  0.015327,     10321.0],
        [0,  0,  1,  2, -0.012528,         0.0],
        [0,  0,  1, -2,  0.010980,     79661.0],
